// oxlint-disable-next-line import/no-nodejs-modules -- The complete original header is tracked, never generated by setup.
import { readFileSync } from 'node:fs';
import { expect, test } from 'vitest';
import { skyMoverRows, skyMoverProgram, SKY_MOVER_HEADER_INPUT } from '../src/shards/far-reach/generators/moverHeader';
import { originalSkyMovers } from './fixtures/sky-movers';

test('mover header source keeps the original complete identity and isolates admitted row loans', async () => {
  const bytes = new Uint8Array(readFileSync(`src/shards/far-reach/${SKY_MOVER_HEADER_INPUT}`));
  const original = originalSkyMovers(); expect(skyMoverRows(bytes)).toEqual(original);
  const row = original[0]; if (row === undefined) throw new Error('Missing original mover');
  row.boxes.length = 0; expect(skyMoverRows(bytes)[0]?.boxes.length).toBeGreaterThan(0);
  expect(() => skyMoverRows(bytes.subarray(1))).toThrow('header identity differs');
  const cached = { cached: () => Promise.resolve(new Map([['movers.json', bytes]])) };
  expect(await skyMoverProgram(cached)).toEqual(skyMoverRows(bytes));
  for (const files of [new Map<string, Uint8Array>(), new Map([['movers.json', new Uint8Array(70_074)]]), new Map([['movers.json', bytes], ['extra', bytes]])]) {
    await expect(skyMoverProgram({ cached: () => Promise.resolve(files) })).rejects.toThrow();
  }
});
